let cfg=null,pendingInvite=null,incomingInvite=null,active=false,posts=[],hasMore=false,loading=false,lastFetch=0,filter='all',imageCache=new Map(),imagePending=new Map(),observer=null,stream=null,draft=null,coords=null,capturedAt=null,baseLink=location.href,status='',noticeTimer,loadGeneration=0,browsingOlder=false,revision=null,accessLost=false,cameraGeneration=0,cameraMode='user',cameraDevices=[],cameraBusy=false;
