function hasInvitation(){return !!incomingInvite}
try{const stored=storedAccess();if(stored){window.MOMENT_DRIVE_TRANSPORT.validate(stored.url);cfg=stored;if(!cfg.token&&cfg.invite)pendingInvite={provider:'google-drive',url:cfg.url,invite:cfg.invite}}const decoded=parseInvite();if(decoded){incomingInvite=decoded;if(cfg?.url!==decoded.url||!cfg?.token)pendingInvite=decoded;else{cfg.invite=decoded.invite;save()}}}catch{status='Questo invito non è valido. Chiedi un nuovo link all’organizzatore.'}
// Refresh a first-party access cookie before iPhone copies cookies to a new Home Screen app.
