function uid(){return cfg?.member?.id||''}
function online(){return navigator.onLine!==false}
function ready(){return !!cfg?.trip&&!!cfg?.token&&!pendingInvite&&!accessLost}
function friendly(e){const t=e.message||'Connessione non riuscita';if(/fetch|network|offline|Failed to fetch/i.test(t))return 'Connessione assente. La foto non è stata pubblicata: mantieni aperta questa schermata e riprova.';return t.slice(0,400)}
function msg(text){status=text;const el=document.querySelector('#moment-status');if(el)el.textContent=text;const toast=document.querySelector('#toast');if(toast){toast.hidden=false;toast.textContent=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>toast.hidden=true,6000)}}
async function rpc(op,data={},auth=true){if(!online())throw Error('offline');if(!cfg?.url)throw Error('Collega prima il diario Google.');const usedUrl=cfg.url,usedToken=cfg.token;try{return await window.MOMENT_DRIVE_TRANSPORT.connect(usedUrl).call({op,data,...(auth?{token:usedToken}:{})})}catch(e){if(e.code==='ACCESS'&&auth&&cfg.url===usedUrl&&cfg.token===usedToken){pendingInvite=incomingInvite;accessLost=!pendingInvite;cfg={url:cfg.url,name:cfg.name,invite:cfg.invite};save();posts=[];for(const url of imageCache.values())URL.revokeObjectURL(url);imageCache.clear();revealedPhotos.clear();seenCards.clear();paintMain();}throw e}}
function japanDate(value){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value))}
function dayLabel(value){return new Intl.DateTimeFormat('it-IT',{timeZone:'Asia/Tokyo',weekday:'long',day:'numeric',month:'long'}).format(new Date(value))}
