function inviteLink(){if(!canInvite())throw Error('Apri Momenti dal link d’invito del gruppo su questo browser, poi potrai copiare il link per gli amici.');const invitation=pendingInvite||cfg,u=new URL('./',baseLink);u.pathname=u.pathname.replace(/Giappone2026\/$/,'');u.search='?2';u.hash=invitation.url===GROUP_URL&&miniMatches(invitation.invite)?miniCode(invitation.invite):invitation.url===GROUP_URL?'m='+compactInvite(invitation.invite):'momenti='+btoa(JSON.stringify({provider:'google-drive',url:invitation.url,invite:invitation.invite})).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');return u.href}
let serviceVersion=Number(cfg?.serviceVersion)||0,socialVersion=0,accountMode='signup',commentsView=null;
