function render(){const header=`<section class="moments-hero ${ready()?'compact':''}"><div class="moments-kicker">${icon('lock')} SOLO NOI, IN VIAGGIO</div><h1>Momenti<span>.</span></h1><p>Il viaggio, da tutti i nostri punti di vista.</p><div class="moments-hero-mark" aria-hidden="true">瞬間</div></section>`;if(accessLost&&!cfg?.invite)return header+`<section class="moments-welcome"><h2>Ritrova il tuo profilo.</h2><button class="primary" data-moment-action="account-login">Accedi con il mio codice</button><p>L’accesso di questo browser non è più valido. Chiedi all’organizzatore un nuovo collegamento; se sei l’organizzatore puoi recuperare l’accesso dalla guida.</p><a class="moment-guide" href="attiva-momenti.html#recupero" target="_blank" rel="noopener">Recupero dell’accesso</a><p id="moment-status" class="moment-status" role="status">${esc(status)}</p></section>`;if(pendingInvite||accessLost&&cfg?.invite)return header+`<section class="moments-welcome"><span class="eyebrow">SEI NEL POSTO GIUSTO</span><h2>Entra nel diario del gruppo.</h2><p>Il tuo nome, le tue foto e i ricordi insieme. Crea un profilo oppure ritrova quello che hai già con il tuo codice personale.</p><div class="moment-auth-choices"><button class="primary" data-moment-action="account-create">Crea il mio profilo ${icon('arrow')}</button><button class="secondary" data-moment-action="account-login">Ho già un codice · Accedi</button></div><p class="moment-fine">Condividi il link solo con gli amici del viaggio.</p><p id="moment-status" class="moment-status" role="status">${esc(status)}</p></section>`;if(!ready())return header+`<section class="moments-welcome"><div class="moment-round">${icon('camera')}</div><h2>I ricordi più belli<br>sono quelli insieme.</h2><p>Scatta un selfie al momento, aggiungi una frase e ritrova le foto di tutti in un unico diario privato.</p>${window.JAPAN_PROGRAM_SHARED?.admin?'<button class="primary" data-moment-action="setup">Attiva Momenti gratuitamente</button><a class="moment-guide" href="attiva-momenti.html" target="_blank" rel="noopener">Apri la guida passo passo</a>':'<p class="moment-invite-help">Per entrare chiedi a Roberto o Leonardo il link d’invito a Momenti. Aprilo su questo telefono per creare il tuo profilo o accedere con il tuo codice.</p>'}<div class="moment-auth-choices"><button class="primary" data-moment-action="account-login">Accedi con il mio codice</button><button class="secondary" data-moment-action="restore-invite">Ho il link del gruppo</button></div><p class="moment-fine">Foto nel Drive dell’organizzatore. Gli amici entrano dal link d’invito.</p><p id="moment-status" class="moment-status" role="status">${esc(status)}</p></section>`;
return header+`<p class="moments-explanation">Scatta un selfie o quello che hai davanti, aggiungi una frase e condividilo. Qui ritrovi le foto di tutti in un diario del viaggio, con giorno, ora e, se vuoi, posizione. Anche quando siamo in posti diversi, il viaggio resta insieme.</p><div class="moment-toolbar"><div><span class="eyebrow">IL NOSTRO DIARIO PRIVATO</span><h2>${esc(cfg.trip.name)}</h2><span class="moment-identity">Sei ${esc(cfg.name)} · orari del Giappone</span></div><button class="primary moment-shoot" data-moment-action="compose">${icon('camera')} Scatta un momento</button></div><div class="moment-controls"><div class="moment-filters" aria-label="Filtra foto"><button data-moment-action="filter-all" class="${filter==='all'?'selected':''}" aria-pressed="${filter==='all'}">Tutti</button><button data-moment-action="filter-mine" class="${filter==='mine'?'selected':''}" aria-pressed="${filter==='mine'}">I miei</button></div><div><button class="text-button" data-moment-action="refresh">Aggiorna</button><button class="text-button" data-moment-action="group">Gruppo</button></div></div><p id="moment-status" class="moment-status" role="status">${esc(status)}</p>${!socialAvailable()?upgradeNotice():!cfg.hasCode?'<p class="moment-account-reminder">Non perdere i tuoi ricordi: <button class="text-button" data-moment-action="account-code">scegli il tuo codice personale</button>.</p>':''}<div id="moment-feed">${feedHTML()}</div><p class="moment-fine">Le foto sono visibili solo al gruppo. Aggiornamento automatico ogni 30 secondi mentre questa sezione è aperta sugli ultimi post. Serve internet.</p>`}
function card(p){const own=p.author_id===uid(),owner=cfg.trip.owner_id===uid(),image=imageCache.get(p.photo_path);return `<article class="moment-card" data-moment-id="${esc(p.id)}"><div class="moment-photo ${image&&revealedPhotos.has(p.photo_path)?'loaded':''} ${imagePending.has(p.photo_path)?'is-loading':''}" data-photo-path="${esc(p.photo_path)}" aria-busy="${imagePending.has(p.photo_path)||!!image&&!revealedPhotos.has(p.photo_path)}">${image?`<img src="${esc(image)}" alt="Momento di ${esc(p.author_name)}" loading="lazy">`:`<button class="moment-load" data-moment-action="photo" data-post="${esc(p.id)}">${icon('camera')} Carica foto</button>`}<span class="moment-time">${timeLabel(p.created_at)} <small>JP</small></span></div><div class="moment-card-body"><div class="moment-author"><span class="moment-avatar">${esc((p.author_name||'?').charAt(0).toUpperCase())}</span><strong>${esc(p.author_name)}</strong>${own?'<span class="moment-you">Tu</span>':''}<span class="moment-location">${esc(p.place_label||'In viaggio')}</span></div>${p.caption?`<p class="moment-caption">${esc(p.caption)}</p>`:''}${socialAvailable()?socialHTML(p):''}<div class="moment-card-foot"><span title="Ora registrata dal server">Pubblicato alle ${timeLabel(p.created_at)}${p.captured_at?` · ${p.source==='camera'?'Scatto':'Scelta foto'} ${timeLabel(p.captured_at)}`:''}</span>${p.latitude!=null&&p.longitude!=null?`<a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(p.latitude+','+p.longitude)}">Posizione ↗</a>`:''}</div><div class="moment-card-actions"><button class="text-button" data-moment-action="download" data-post="${esc(p.id)}">Salva foto</button>${own||owner?`<button class="text-button danger-text" data-moment-action="delete" data-post="${esc(p.id)}">Elimina</button>`:''}</div></div></article>`}

function commentHTML(c,p){const own=c.author_id===uid()||cfg.trip.owner_id===uid();return '<li class="moment-comment" data-comment-id="'+esc(c.id)+'"><span class="comment-avatar" aria-hidden="true">'+esc((c.author_name||'?').charAt(0).toUpperCase())+'</span><div><p><strong>'+esc(c.author_name)+'</strong> '+esc(c.text)+'</p><small>'+timeLabel(c.created_at)+' · JP</small></div>'+(own?'<button type="button" class="text-button comment-remove" data-moment-action="delete-comment" data-comment="'+esc(c.id)+'" data-post="'+esc(p.id)+'" aria-label="Elimina questo commento">×</button>':'')+'</li>'}
function commentForm(p,suffix=''){return '<form class="moment-comment-form" data-comment-form data-post="'+esc(p.id)+'"><label class="visually-hidden" for="comment-'+esc(p.id)+suffix+'">Commenta come '+esc(cfg.name)+'</label><input id="comment-'+esc(p.id)+suffix+'" name="comment" data-comment-input data-post="'+esc(p.id)+'" type="text" maxlength="600" required placeholder="Commenta come '+esc(cfg.name)+'…" value="'+esc(commentDrafts.get(p.id)||'')+'" autocomplete="off"><button type="submit" aria-label="Invia commento" '+(socialBusy.has('comment:'+p.id)?'disabled':'')+'>Invia</button></form>'}
function socialHTML(p){return '<section class="moment-social" aria-label="Like e commenti"><div class="moment-social-toolbar"><button type="button" class="moment-like '+(p.liked?'is-liked':'')+'" aria-pressed="'+!!p.liked+'" aria-label="'+(p.liked?'Togli il like':'Mi piace')+'" data-moment-action="like" data-post="'+esc(p.id)+'" '+(socialBusy.has('like:'+p.id)?'disabled':'')+'><span aria-hidden="true">'+(p.liked?'♥':'♡')+'</span> <strong>'+Number(p.like_count||0)+'</strong></button><button type="button" class="text-button moment-comment-count" data-moment-action="comments" data-post="'+esc(p.id)+'">'+Number(p.comment_count||0)+' '+(p.comment_count===1?'commento':'commenti')+'</button></div>'+(p.comments?.length?'<ol class="moment-comments-preview">'+p.comments.map(c=>commentHTML(c,p)).join('')+'</ol>':'')+commentForm(p)+'</section>'}
function applySocial(p,data){if(!posts.some(x=>x.id===p.id))return;Object.assign(p,data.social);socialVersion++;revision=null}
async function likePhoto(p){const key='like:'+p.id;if(socialBusy.has(key))return;socialBusy.add(key);let confirmed=false;paintFeed();try{const result=await rpc('like',{id:p.id,liked:!p.liked});applySocial(p,result);confirmed=!!p.liked}catch(e){msg(friendly(e))}finally{socialBusy.delete(key);paintFeed();if(confirmed)window.JAPAN_MOTION?.social(p.id,'like')}}
async function sendComment(form){
 const p=posts.find(p=>p.id===form.dataset.post);if(!p)return;const input=form.querySelector('input'),text=input.value.trim();if(!text)return;
 const key='comment:'+p.id;if(socialBusy.has(key))return;socialBusy.add(key);commentDrafts.set(p.id,input.value);
 const previous=commentAttempts.get(p.id),attempt=previous?.text===text?previous:{id:crypto.randomUUID(),text};commentAttempts.set(p.id,attempt);
 form.querySelector('button').disabled=true;let confirmed=false;
 try{const data=await rpc('comment',{id:p.id,commentId:attempt.id,text});applySocial(p,data);confirmed=true;if((commentDrafts.get(p.id)||'').trim()===text){commentDrafts.delete(p.id);input.value=''}commentAttempts.delete(p.id);msg('Commento inviato come '+cfg.name+'.');socialBusy.delete(key);if(commentsView?.post===p.id&&document.querySelector('#moment-dialog')?.open)await showComments(p)}
 catch(e){msg(friendly(e))}
 finally{socialBusy.delete(key);paintFeed();if(confirmed)window.JAPAN_MOTION?.social(p.id,'comment',attempt.id);if(form.isConnected)form.querySelector('button').disabled=false;}
}
async function showComments(p,older=false){
 const before=older&&commentsView?.comments[0],data=await rpc('comments',{id:p.id,...(before?{before:{time:before.created_at,id:before.id}}:{})});
 commentsView={post:p.id,comments:older?[...data.comments,...commentsView.comments]:data.comments,hasMore:data.hasMore};
 dialog('Sotto il momento di '+esc(p.author_name),'<div class="moment-comments-panel"><ol class="moment-comments-list">'+commentsView.comments.map(c=>commentHTML(c,p)).join('')+'</ol>'+(data.hasMore?'<button type="button" class="secondary" data-moment-action="older-comments" data-post="'+esc(p.id)+'">Commenti precedenti</button>':'')+(!commentsView.comments.length?'<p class="moment-fine">Il primo commento può essere il tuo.</p>':'')+commentForm(p,'-dialog')+'</div>');
}
async function removeComment(p,id){if(!window.confirm('Eliminare questo commento?'))return;const data=await rpc('deleteComment',{id:p.id,commentId:id});applySocial(p,data);paintFeed();if(commentsView?.post===p.id&&document.querySelector('#moment-dialog')?.open)await showComments(p);}
let interactiveLoading=false;
function loadingHTML(){return '<section class="moments-empty moments-loading" aria-busy="true"><button type="button" class="moments-loader-scene" data-moment-action="loading-play" aria-label="Tocca per animare i ricordi mentre aspetti"><span class="loader-polaroid loader-left" aria-hidden="true">⛩️</span><span class="loader-polaroid loader-right" aria-hidden="true">🤳</span><span class="loader-polaroid loader-front" aria-hidden="true"><span data-loading-emoji>🌸</span></span></button><div role="status" aria-live="polite"><h3>Carichiamo i vostri ricordi…</h3><p>Un istante e ci siamo.</p><span class="loader-dots" aria-hidden="true"><i></i><i></i><i></i></span></div><p class="loader-play-hint">Tocca le foto per un po’ di magia ✨</p></section>'}
function playLoading(el){
 const next=(Number(el.dataset.play)||0)+1;el.dataset.play=String(next);const emoji=el.querySelector('[data-loading-emoji]');if(emoji)emoji.textContent=['🌸','🍣','🗻','⛩️'][next%4];
 if(reducedMotion()||!el.animate)return;
 el.getAnimations?.().forEach(m=>m.cancel());el.querySelectorAll('.loader-spark').forEach(s=>s.remove());
 el.animate([{transform:'scale(1)'},{transform:'scale(1.06)',offset:.45},{transform:'scale(1)'}],{duration:340,easing:'ease-out'});
 for(let i=0;i<4;i++){const star=document.createElement('span');star.className='loader-spark';star.textContent='✦';star.setAttribute('aria-hidden','true');el.appendChild(star);
 const angle=i*Math.PI/2+Math.PI/4,x=Math.cos(angle)*85,y=Math.sin(angle)*60,motion=star.animate([{opacity:0,transform:'translate(-50%,-50%) scale(.3)'},{opacity:1,offset:.25},{opacity:0,transform:'translate(calc(-50% + '+x+'px),calc(-50% + '+y+'px)) scale(1.2)'}],{duration:580,easing:'ease-out'});motion.onfinish=()=>star.remove();motion.oncancel=()=>star.remove();}
}
function feedHTML(){const visible=posts.filter(p=>filter!=='mine'||p.author_id===uid());if(!visible.length&&loading&&interactiveLoading)return loadingHTML();if(!visible.length)return `<div class="moments-empty">${icon('camera')}<h3>${filter==='mine'?'Il tuo primo momento ti aspetta.':'Il viaggio comincia da qui.'}</h3><p>${online()?'Scatta il primo selfie e apri il diario del gruppo.':'Sei offline. Il programma resta consultabile; le foto richiedono internet.'}</p></div>`;let day='',html='';for(const p of visible){const d=japanDate(p.created_at);if(d!==day){if(day)html+='</div>';day=d;html+=`<h3 class="moment-day">${esc(dayLabel(p.created_at))}</h3><div class="moment-grid">`}html+=card(p)}return html+'</div>'+ (hasMore?'<button class="secondary moment-older" data-moment-action="older">'+(loading?'Caricamento…':'Mostra momenti precedenti')+'</button>':'<p class="moment-end">L’inizio dei nostri ricordi.</p>')}
function paintFeed(){const el=document.querySelector('#moment-feed');if(el){
 // Reuse the photo elements: preserve an image that is loading or already visible.
 const focused=document.activeElement?.matches('[data-comment-input]')?{post:document.activeElement.dataset.post,start:document.activeElement.selectionStart,end:document.activeElement.selectionEnd}:null;
 const photos=new Map([...el.querySelectorAll('[data-moment-id]')].map(card=>[card.dataset.momentId,card.querySelector('[data-photo-path]')]));
 el.innerHTML=feedHTML();el.querySelectorAll('[data-moment-id]').forEach(card=>{const old=photos.get(card.dataset.momentId),fresh=card.querySelector('[data-photo-path]');if(old&&fresh&&old.dataset.photoPath===fresh.dataset.photoPath)fresh.replaceWith(old)});hydrate();if(focused){const input=[...el.querySelectorAll('[data-comment-input]')].find(input=>input.dataset.post===focused.post);if(input){input.focus({preventScroll:true});input.setSelectionRange(focused.start,focused.end)}}
 }document.querySelectorAll('.moment-filters button').forEach(b=>{const on=b.dataset.momentAction==='filter-'+filter;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on)})}
function paintMain(){if(active)document.querySelector('#main').innerHTML=render();hydrate()}
async function loadFeed(older=false,force=false){if(!ready()||loading)return;loading=true;interactiveLoading=!posts.length&&(!lastFetch||force||older);if(interactiveLoading)paintFeed();const generation=loadGeneration,socialAtFetch=socialVersion;let repaint=older;
 try{const last=posts.at(-1),data=await rpc('feed',{mine:filter==='mine',limit:PAGE,...(older&&last?{before:{time:last.created_at,id:last.id}}:{}),...(!older&&!force&&revision?{revision}:{})});if(generation!==loadGeneration)return;if(socialAtFetch!==socialVersion){revision=null;return;}
 const beforeVersion=serviceVersion,beforeName=cfg.name;serviceVersion=Number(data.version)||0;if(data.member){cfg.member=data.member;cfg.name=data.member.name;}if(data.hasCode!=null)cfg.hasCode=data.hasCode;cfg.serviceVersion=serviceVersion;save();if(beforeVersion!==serviceVersion||beforeName!==cfg.name)paintMain();
 if(!data.unchanged){repaint=true;hasMore=data.hasMore;posts=older?[...posts,...data.posts.filter(p=>!posts.some(a=>a.id===p.id))]:data.posts;revision=data.revision;if(data.trip)cfg.trip=data.trip;trimImages();}
 browsingOlder=older;lastFetch=Date.now();status=browsingOlder?'Cronologia precedente · premi Aggiorna per tornare agli ultimi momenti.':'Aggiornato alle '+timeLabel(new Date())+' · ora del Giappone';document.querySelector('#moment-status')?.replaceChildren(document.createTextNode(status));
 }catch(e){repaint=true;msg(friendly(e))}finally{loading=false;interactiveLoading=false;if(generation===loadGeneration&&(repaint||!posts.length))paintFeed();if(socialAtFetch!==socialVersion&&!browsingOlder)setTimeout(()=>{if(active)void loadFeed(false,true)},0)}}
function trimImages(){const retained=new Set(posts.map(p=>p.photo_path));for(const [path,url]of imageCache)if(!retained.has(path)){URL.revokeObjectURL(url);imageCache.delete(path);revealedPhotos.delete(path)}}
async function photo(p){
 if(imageCache.has(p.photo_path))return imageCache.get(p.photo_path);if(imagePending.has(p.photo_path))return imagePending.get(p.photo_path);photoBusy(p,true);
 const work=(async()=>{try{
 const data=await rpc('photo',{id:p.id});if(data.mimeType!=='image/jpeg'||typeof data.photo!=='string'||data.photo.length>Math.ceil(MAX_BYTES/3)*4)throw Error('La foto non è disponibile.');
 const binary=atob(data.photo),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'image/jpeg'}));if(!posts.some(a=>a.id===p.id)||accessLost){URL.revokeObjectURL(url);return null}
 imageCache.set(p.photo_path,url);document.querySelectorAll('[data-photo-path]').forEach(el=>{if(el.dataset.photoPath===p.photo_path)mountPhoto(el,p,url)});return url;
 }catch(e){photoBusy(p,false);msg(friendly(e));return null}finally{imagePending.delete(p.photo_path)}})();imagePending.set(p.photo_path,work);return work;
}
function hydrate(){window.JAPAN_MOTION?.ambient();observer?.disconnect();if(!active||!ready())return;
 document.querySelectorAll('[data-moment-id]').forEach(el=>{const p=posts.find(p=>p.id===el.dataset.momentId);if(!p||seenCards.has(photoKey(p)))return;seenCards.add(photoKey(p));if(!reducedMotion()){el.classList.add('moment-arrival');el.addEventListener('animationend',()=>el.classList.remove('moment-arrival'),{once:true})}});
 document.querySelectorAll('[data-photo-path]').forEach(el=>{const p=posts.find(p=>p.photo_path===el.dataset.photoPath),img=el.querySelector('img');if(p&&img)watchPhoto(el,p,img)});
 if('IntersectionObserver'in window){observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){observer.unobserve(e.target);const p=posts.find(p=>p.photo_path===e.target.dataset.photoPath);if(p&&!imageCache.has(p.photo_path))void photo(p)}},{rootMargin:'100px'});document.querySelectorAll('[data-photo-path]').forEach(el=>{if(!el.classList.contains('loaded'))observer.observe(el)})}
}
function onView(isActive,link){active=isActive;baseLink=link||baseLink;if(active){hydrate();if(ready()&&!browsingOlder&&Date.now()-lastFetch>30000)void loadFeed()}else observer?.disconnect()}
function dialog(title,content){let el=document.querySelector('#moment-dialog');if(!el){el=document.createElement('dialog');el.id='moment-dialog';el.className='moment-dialog';document.body.append(el);el.addEventListener('close',()=>{stopCamera();if(draft?.url){URL.revokeObjectURL(draft.url);draft=null}});el.addEventListener('cancel',e=>{if(el.dataset.busy==='true'){e.preventDefault();return}stopCamera()})}el.innerHTML=`<div class="dialog-heading"><h2>${title}</h2><button type="button" class="icon-button" data-moment-action="close" aria-label="Chiudi">×</button></div>${content}<p id="moment-error" class="form-error" role="alert"></p>`;el.dataset.busy='false';if(!el.open)el.showModal();return el}
