function personalCode(value){const code=String(value||'').trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code)||!/[A-Z]/.test(code)||!/[0-9]/.test(code))throw Error('Scegli esattamente 6 lettere e numeri, con almeno una lettera e un numero.');return code}
