function importInvitation(value){let hash=String(value||'').trim();if(/^https?:/i.test(hash)){const url=new URL(hash);if(url.origin!==location.origin||!url.pathname.startsWith('/Giappone-2026/'))throw Error('Usa il link del viaggio che hai ricevuto dagli amici.');hash=url.hash;}const invite=parseInvite(hash);if(!invite)throw Error('Incolla il link completo d’invito, compresa la parte dopo #.');pendingInvite=invite;incomingInvite=invite;accessLost=false;rememberHomeAccess(invite);return invite}
