  cfg={url:invitation.url,invite:invitation.invite,name:result.member.name,member:result.member,token:result.token,trip:result.trip,hasCode:!!result.hasCode,serviceVersion:Number(result.version)||0};serviceVersion=Number(result.version)||0;
