function accessAttempt(op,url,name,invite=''){
 const old=cfg?.pendingAccess;
 if(old&&old.op===op&&old.url===url&&old.name===name&&old.invite===invite&&/^[a-f0-9]{64}$/.test(old.key))return old;
 return {op,url,name,invite,key:(crypto.randomUUID()+crypto.randomUUID()).replaceAll('-','')};
}

