function group(){const owner=cfg.trip.owner_id===uid();dialog('Il nostro gruppo',`<p><strong>${esc(cfg.trip.name)}</strong><br>Sei ${esc(cfg.name)} su questo browser.</p><p>Le foto sono conservate nel Drive dell’organizzatore. Gli amici vedono il diario dall’app, senza aprire Drive.</p><p>Un unico link per consultare il programma e partecipare a Momenti. Chi lo riceve crea il proprio profilo o accede con il codice personale; non può modificare il programma.</p><div class="moment-group-buttons"><button class="primary" data-moment-action="invite">Copia invito per gli amici</button><button class="secondary" data-moment-action="rename">Cambia il mio nome</button><button class="secondary" data-moment-action="account-code">${cfg.hasCode?'Cambia il mio codice':'Scegli il mio codice personale'}</button><button class="secondary" data-moment-action="home-help">Aggiungi alla Home dell’iPhone</button><button class="text-button" data-moment-action="account-switch">Accedi con un altro profilo</button>${owner?'<button class="secondary" data-moment-action="rotate">Genera un nuovo invito</button><button class="secondary" data-moment-action="members">Gestisci partecipanti</button>':''}</div><p id="moment-invite-output" class="moment-link" hidden></p><p class="moment-fine">Condividi l’invito solo con il gruppo. Un nuovo invito blocca i vecchi link; gli amici già entrati rimangono collegati.</p><p class="moment-fine">L’accesso resta memorizzato su questo browser. Su un altro telefono, o dopo aver cancellato i dati, apri l’invito e usa il tuo codice: ritroverai lo stesso nome e le tue foto. Non condividere il codice personale. L’organizzatore può recuperare il proprio accesso eseguendo di nuovo inizializzaMomenti nel suo Apps Script.</p><a href="attiva-momenti.html#limiti" target="_blank" rel="noopener">Spazio, privacy e conservazione dei ricordi</a>`)}
async function copyInvite(){let link;try{link=inviteLink();await navigator.clipboard.writeText(link);msg('Link copiato: programma e Momenti insieme. Mandalo agli amici su WhatsApp.')}catch(e){if(!link){msg(friendly(e));return}let el=document.querySelector('#moment-invite-output');if(!el||(el.closest('dialog')&&!el.closest('dialog').open)){dialog('Link per gli amici','<p>Questo invito apre il programma e Momenti. Copialo e mandalo al gruppo WhatsApp.</p><p id="moment-invite-output" class="moment-link"></p>');el=document.querySelector('#moment-invite-output')}if(el){el.hidden=false;el.textContent=link;try{const range=document.createRange();range.selectNodeContents(el);getSelection().removeAllRanges();getSelection().addRange(range)}catch{}msg('Link pronto: tieni premuto sul testo per copiarlo e mandarlo agli amici.')}}}
function field(id,label,value='',type='text',extra=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function cameraControls(live=false,busy=false){
 const captureButton=document.querySelector('[data-moment-action="capture"]'),cameraButton=document.querySelector('[data-moment-action="camera"]');
 if(captureButton){captureButton.hidden=!live;captureButton.disabled=busy}
 if(cameraButton){cameraButton.hidden=live;cameraButton.disabled=busy;cameraButton.textContent=draft?'Rifai la foto':'Apri fotocamera'}
 for(const button of document.querySelectorAll('[data-moment-action="camera-front"],[data-moment-action="camera-back"]')){button.disabled=busy;button.setAttribute('aria-pressed',String(button.dataset.momentAction===(cameraMode==='user'?'camera-front':'camera-back')))}
 const choices=document.querySelector('#moment-camera-device');if(choices)choices.disabled=busy;
 const status=document.querySelector('#moment-camera-status');if(status)status.textContent=busy?'Apertura fotocamera…':live?(cameraMode==='user'?'Fotocamera frontale':'Fotocamera posteriore'):'Scegli frontale o posteriore, poi apri la fotocamera.';
}
function stopCamera(){cameraGeneration++;cameraBusy=false;stream?.getTracks().forEach(t=>t.stop());stream=null;const video=document.querySelector('#moment-video');if(video){video.srcObject=null;video.hidden=true}cameraControls();const placeholder=document.querySelector('#moment-camera-placeholder');if(placeholder)placeholder.hidden=!!draft}
function paintCameraDevices(){
 const picker=document.querySelector('#moment-camera-device'),wrap=document.querySelector('#moment-camera-device-field');if(!picker||!wrap)return;
 const selected=stream?.getVideoTracks()[0]?.getSettings?.().deviceId;
 picker.innerHTML='<option value="">Obiettivo automatico</option>'+cameraDevices.map((device,i)=>'<option value="'+esc(device.deviceId)+'" '+(device.deviceId===selected?'selected':'')+'>'+esc(device.label||'Fotocamera '+(i+1))+'</option>').join('');
 wrap.hidden=cameraDevices.length<3;picker.disabled=cameraBusy;
}
function compose(){if(!online()){msg('Per pubblicare un momento serve internet.');return}stopCamera();if(draft?.url)URL.revokeObjectURL(draft.url);draft=null;coords=null;capturedAt=null;cameraMode='user';cameraDevices=[];dialog('Questo momento è nostro.',`<div class="moment-camera"><video id="moment-video" autoplay playsinline muted hidden></video><img id="moment-preview" alt="La tua foto prima della pubblicazione" hidden><div id="moment-camera-placeholder">${icon('camera')}<p>Un selfie o il panorama?</p></div></div><div class="moment-camera-choice" role="group" aria-label="Scegli fotocamera"><button class="secondary" data-moment-action="camera-front" aria-pressed="true">🤳 Frontale</button><button class="secondary" data-moment-action="camera-back" aria-pressed="false">📷 Posteriore</button></div><div id="moment-camera-device-field" class="field" hidden><label for="moment-camera-device">Fotocamera / obiettivo</label><select id="moment-camera-device"></select></div><p id="moment-camera-status" class="moment-fine" role="status">Scegli frontale o posteriore, poi apri la fotocamera.</p><div class="moment-camera-actions"><button class="primary" data-moment-action="camera">Apri fotocamera</button><button class="primary" data-moment-action="capture" hidden>Scatta</button><button class="secondary" data-moment-action="pick">Scegli una foto</button><input id="moment-file" type="file" accept="image/*" hidden></div><p class="moment-fine camera-lens-help">Non trovi il grandangolo 0,5×? Scatta con l’app Fotocamera del telefono e usa “Scegli una foto”.</p><form id="moment-post-form"><div class="field"><label for="moment-caption">Una frase per ricordarlo <span>(facoltativa)</span></label><textarea id="moment-caption" maxlength="600" rows="3" placeholder="Persi a Tokyo. Felici, però."></textarea></div>${field('moment-place','Dove siete? (facoltativo)','','text','maxlength="100" placeholder="Es. Shibuya, Tokyo"')}<div class="moment-gps-row"><button type="button" class="secondary" data-moment-action="gps">Aggiungi posizione GPS</button><button type="button" class="text-button" data-moment-action="remove-gps" hidden>Rimuovi</button></div><p id="moment-gps-status" class="moment-fine">La posizione viene condivisa soltanto se la aggiungi.</p><p id="moment-photo-status" class="moment-fine"></p><button class="primary moment-publish" type="submit" disabled>Pubblica nel gruppo ${icon('arrow')}</button></form>`)}
function cameraDeviceMode(deviceId,fallback=cameraMode){const label=cameraDevices.find(device=>device.deviceId===deviceId)?.label||'';if(/back|rear|posteriore|environment|arrière|rück/i.test(label))return 'environment';if(/front|user|anteriore|facetime|avant/i.test(label))return 'user';return fallback}
async function startCamera(mode=cameraMode,deviceId=''){
 if(cameraBusy)return;
 if(deviceId)mode=cameraDeviceMode(deviceId,mode);
 stopCamera();cameraMode=mode;cameraBusy=true;const generation=cameraGeneration;cameraControls(false,true);
 const current=()=>generation===cameraGeneration&&!!document.querySelector('#moment-video')&&!!document.querySelector('#moment-dialog')?.open;
 try{
  if(!navigator.mediaDevices?.getUserMedia)throw Error('Fotocamera non disponibile: usa Scegli una foto.');
  const settings={width:{ideal:1600},height:{ideal:1200}};
  let acquired;
  try{acquired=await navigator.mediaDevices.getUserMedia({video:{...settings,...(deviceId?{deviceId:{exact:deviceId}}:{facingMode:{exact:mode}})},audio:false})}
  catch(error){if(deviceId||!['OverconstrainedError','NotFoundError'].includes(error.name)||!current())throw error;acquired=await navigator.mediaDevices.getUserMedia({video:{...settings,facingMode:{ideal:mode}},audio:false})}
  if(!current()){acquired.getTracks().forEach(track=>track.stop());return}
  stream=acquired;const video=document.querySelector('#moment-video'),track=stream.getVideoTracks()[0],actual=track?.getSettings?.().facingMode;
  if(actual==='user'||actual==='environment')cameraMode=actual;
  video.dataset.facing=cameraMode;video.srcObject=stream;video.hidden=false;await video.play();
  if(!current())return;
  document.querySelector('#moment-preview').hidden=true;document.querySelector('#moment-camera-placeholder').hidden=true;document.querySelector('#moment-error').textContent='';
  cameraBusy=false;cameraControls(true);
  if(actual&&actual!==mode&&!deviceId)document.querySelector('#moment-camera-status').textContent='Questa è la fotocamera disponibile sul dispositivo.';
  try{cameraDevices=(await navigator.mediaDevices.enumerateDevices()).filter(device=>device.kind==='videoinput'&&device.deviceId);if(current())paintCameraDevices()}catch{}
 }catch(error){if(!current())return;stopCamera();const message=document.querySelector('#moment-error');if(message)message.textContent=error.name==='NotAllowedError'?'Accesso alla fotocamera negato. Puoi usare Scegli una foto o riattivare il permesso nelle impostazioni del browser.':error.name==='NotFoundError'||error.name==='OverconstrainedError'?'Questa fotocamera non è disponibile. Prova l’altra o usa Scegli una foto.':friendly(error)}
 finally{if(generation===cameraGeneration&&cameraBusy){cameraBusy=false;cameraControls(!!stream)}}
}
async function chooseCamera(mode){if(cameraBusy)return;cameraMode=mode;const picker=document.querySelector('#moment-camera-device');if(picker)picker.value='';if(stream)await startCamera(mode);else cameraControls()}
document.addEventListener('change',event=>{if(event.target.id==='moment-camera-device')void startCamera(cameraMode,event.target.value)});

async function compressed(image,w,h){if(!w||!h)throw Error('La foto non è leggibile.');const scale=Math.min(1,1200/Math.max(w,h)),canvas=document.createElement('canvas');canvas.width=Math.round(w*scale);canvas.height=Math.round(h*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let blob;for(const quality of [.82,.68,.52,.38]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=MAX_BYTES)break}if(!blob||blob.size>MAX_BYTES)throw Error('Questa foto è troppo grande. Scegline un’altra.');return blob}
function usePhoto(blob,source){if(draft?.url)URL.revokeObjectURL(draft.url);draft={blob,url:URL.createObjectURL(blob),source};capturedAt=new Date().toISOString();stopCamera();document.querySelector('#moment-video').hidden=true;const image=document.querySelector('#moment-preview');image.src=draft.url;image.hidden=false;document.querySelector('#moment-camera-placeholder').hidden=true;document.querySelector('[data-moment-action="capture"]').hidden=true;document.querySelector('[data-moment-action="camera"]').hidden=false;document.querySelector('[data-moment-action="camera"]').textContent='Rifai la foto';document.querySelector('.moment-publish').disabled=false;document.querySelector('#moment-photo-status').textContent=`${source==='camera'?'Foto scattata ora':'Foto selezionata ora'} · ${Math.ceil(blob.size/1000)} KB. Verrà inviata solo quando premi Pubblica.`;document.querySelector('#moment-error').textContent=''}
async function capture(){try{const v=document.querySelector('#moment-video');usePhoto(await compressed(v,v.videoWidth,v.videoHeight),'camera')}catch(e){document.querySelector('#moment-error').textContent=friendly(e)}}
async function pickFile(file){if(!file)return;try{if(file.size>25000000)throw Error('Scegli una foto più piccola di 25 MB.');const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Formato non leggibile. Su iPhone scegli una foto JPEG oppure usa la fotocamera.'));img.src=url});usePhoto(await compressed(img,img.naturalWidth,img.naturalHeight),'gallery')}finally{URL.revokeObjectURL(url)}}catch(e){document.querySelector('#moment-error').textContent=friendly(e)}}
function gps(){const b=document.querySelector('[data-moment-action="gps"]'),target=document.querySelector('#moment-gps-status');b.disabled=true;document.querySelector('#moment-gps-status').textContent='Cerchiamo la posizione…';if(!navigator.geolocation){b.disabled=false;msg('GPS non disponibile. Puoi scrivere il nome del luogo.');return}navigator.geolocation.getCurrentPosition(p=>{b.disabled=false;if(document.querySelector('#moment-gps-status')!==target||!document.querySelector('#moment-dialog')?.open)return;coords={latitude:Number(p.coords.latitude.toFixed(4)),longitude:Number(p.coords.longitude.toFixed(4))};document.querySelector('#moment-gps-status').textContent='Posizione aggiunta: '+coords.latitude+', '+coords.longitude+' · precisione circa '+Math.round(p.coords.accuracy)+' m. Sarà visibile al gruppo.';document.querySelector('[data-moment-action="remove-gps"]').hidden=false},e=>{b.disabled=false;if(document.querySelector('#moment-gps-status')!==target)return;document.querySelector('#moment-gps-status').textContent=e.code===1?'Permesso GPS negato. Il post potrà essere pubblicato senza posizione.':'Posizione non disponibile. Riprova o scrivi il nome del luogo.'},{enableHighAccuracy:false,timeout:12000,maximumAge:0})}
async function blobBase64(blob){const bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary)}
async function publish(){if(!draft)return;const el=document.querySelector('#moment-dialog'),b=el.querySelector('.moment-publish');el.dataset.busy='true';el.querySelectorAll('button').forEach(button=>button.disabled=true);b.textContent='Pubblicazione…';try{draft.id=draft.id||crypto.randomUUID();const photo=await blobBase64(draft.blob);await rpc('publish',{id:draft.id,photo,caption:document.querySelector('#moment-caption').value.trim(),place:document.querySelector('#moment-place').value.trim(),captured_at:capturedAt,source:draft.source,latitude:coords?.latitude??null,longitude:coords?.longitude??null});el.close();if(draft?.url)URL.revokeObjectURL(draft.url);draft=null;await loadFeed(false,true);msg('Momento pubblicato. Gli amici lo vedranno nel diario.')}catch(e){document.querySelector('#moment-error').textContent=friendly(e)}finally{el.dataset.busy='false';el.querySelectorAll('button').forEach(button=>button.disabled=false);b.disabled=!draft;b.innerHTML='Pubblica nel gruppo '+icon('arrow')}}
function confirmDelete(p){dialog('Eliminare questo momento?',`<p>Il post di ${esc(p.author_name)} verrà rimosso dal diario e la foto spostata nel cestino del Drive dell’organizzatore.</p><div class="dialog-actions"><button class="secondary" data-moment-action="close">Annulla</button><button class="primary" data-moment-action="confirm-delete" data-post="${esc(p.id)}">Elimina momento</button></div>`)}
async function deletePost(p){const el=document.querySelector('#moment-dialog');el.dataset.busy='true';el.querySelectorAll('button').forEach(b=>b.disabled=true);try{const result=await rpc('delete',{id:p.id});posts=posts.filter(a=>a.id!==p.id);trimImages();revision=null;el.close();paintFeed();msg(result.cleaned?'Momento eliminato dal diario. La foto è nel cestino di Drive.':'Post rimosso dal diario. L’organizzatore deve spostare la foto nel cestino direttamente da Drive.')}catch(e){document.querySelector('#moment-error').textContent=friendly(e)}finally{el.dataset.busy='false';el.querySelectorAll('button').forEach(b=>b.disabled=false)}}
async function members(){const list=await rpc('members');dialog('I compagni di viaggio',`<p>${list.length} partecipanti nel diario. Rimuovere una persona revoca il suo accesso e cambia anche l’invito, così il vecchio link non permette di rientrare.</p><div class="moment-member-list">${list.map(m=>`<div class="moment-member"><strong>${esc(m.name)}</strong>${m.id===uid()?'<span>Tu · organizzatore</span>':`<button class="text-button danger-text" data-moment-action="remove-member" data-member="${esc(m.id)}" data-name="${esc(m.name)}">Rimuovi</button><button class="text-button" data-moment-action="reset-member-code" data-member="${esc(m.id)}">Nuovo codice</button>`}</div>`).join('')}</div>`)}
document.addEventListener('submit',e=>{if(e.target.id==='moment-invitation-form'){e.preventDefault();try{importInvitation(document.querySelector('#moment-invite-link').value);document.querySelector('#moment-dialog').close();paintMain();void accountDialog(accountMode).catch(error=>msg(friendly(error)))}catch(error){document.querySelector('#moment-error').textContent=friendly(error)}return;}if(e.target.matches('[data-comment-form]')){e.preventDefault();void sendComment(e.target);return;}if(e.target.id==='moment-account-form'){e.preventDefault();void submitAccount();return;}if(e.target.id==='moment-code-form'){e.preventDefault();void submitCode();return;}const id=e.target.id;if(!['moment-setup-form','moment-join-form','moment-post-form'].includes(id))return;e.preventDefault();if(document.querySelector('#moment-dialog').dataset.busy==='true')return;void(id==='moment-post-form'?publish():submitAccess(id==='moment-setup-form'?'setup':'join'))});
document.addEventListener('change',e=>{if(e.target.id==='moment-file')void pickFile(e.target.files[0])});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-moment-action]');if(!el)return;const action=el.dataset.momentAction,p=posts.find(p=>p.id===el.dataset.post),d=document.querySelector('#moment-dialog');if(d?.dataset.busy==='true')return;try{switch(action){case'loading-play':playLoading(el);break;case'restore-invite':restoreInvitation();break;case'home-help':homeInstructions();break;case'show-code':{const input=document.querySelector('#moment-personal-code'),show=input.type==='password';for(const id of ['#moment-personal-code','#moment-code-confirm']){const field=document.querySelector(id);if(field)field.type=show?'text':'password';}el.textContent=show?'Nascondi codice':'Mostra codice';break;}case'account-create':await accountDialog('signup');break;case'account-login':case'account-switch':await accountDialog('login');break;case'account-code':await codeDialog();break;case'like':if(p)await likePhoto(p);break;case'comments':if(p)await showComments(p);break;case'older-comments':if(p)await showComments(p,true);break;case'delete-comment':if(p)await removeComment(p,el.dataset.comment);break;case'reset-member-code':await codeDialog(el.dataset.member);break;case'setup':setup();break;case'join':join();break;case'close':d.close();break;case'compose':compose();break;case'camera':await startCamera();break;case'camera-front':await chooseCamera('user');break;case'camera-back':await chooseCamera('environment');break;case'capture':await capture();break;case'pick':document.querySelector('#moment-file').click();break;case'gps':gps();break;case'remove-gps':coords=null;document.querySelector('#moment-gps-status').textContent='Posizione rimossa. Non verrà condivisa.';el.hidden=true;break;case'refresh':await loadFeed(false,true);break;case'older':await loadFeed(true);break;case'filter-all':case'filter-mine':if(loading)break;filter=action==='filter-all'?'all':'mine';posts=[];revision=null;lastFetch=0;loadGeneration++;await loadFeed(false,true);break;case'photo':if(p)await photo(p);break;case'group':group();break;case'invite':await copyInvite();break;case'rename':pendingInvite=null;join();break;case'rotate':dialog('Sostituire il link d’invito?',`<p>Il vecchio link non permetterà più di entrare. Gli amici già nel gruppo rimarranno collegati.</p><button class="primary" data-moment-action="confirm-rotate">Genera nuovo link</button>`);break;case'confirm-rotate':{const data=await rpc('rotate');cfg.invite=data.invite;save();group();msg('Nuovo invito pronto. Copialo e mandalo agli amici.');break}case'download':if(p){const url=await photo(p);if(url){const a=document.createElement('a');a.href=url;a.download='Giappone-'+japanDate(p.created_at)+'-'+p.id.slice(0,8)+'.jpg';a.click()}}break;case'delete':if(p)confirmDelete(p);break;case'confirm-delete':if(p)await deletePost(p);break;case'members':await members();break;case'remove-member':dialog('Rimuovere '+esc(el.dataset.name)+'?',`<p>La persona perderà l’accesso al diario. Anche il link d’invito cambierà; gli altri partecipanti resteranno collegati.</p><button class="primary" data-moment-action="confirm-remove-member" data-member="${esc(el.dataset.member)}">Rimuovi e cambia invito</button>`);break;case'confirm-remove-member':{const result=await rpc('removeMember',{id:el.dataset.member});cfg.invite=result.invite;save();group();msg('Accesso revocato. Se serve, copia il nuovo invito per il gruppo.');break}}}catch(error){const current=document.querySelector('#moment-dialog');if(current?.open&&current.querySelector('#moment-error'))current.querySelector('#moment-error').textContent=friendly(error);else msg(friendly(error))}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCamera();else if(active&&ready()&&!browsingOlder&&Date.now()-lastFetch>30000)void loadFeed()});window.addEventListener('pagehide',stopCamera);window.addEventListener('online',()=>{if(active)void loadFeed(false,true)});window.addEventListener('offline',()=>{if(active)msg('Sei offline. Le foto richiedono internet; il programma resta disponibile.')});setInterval(()=>{if(active&&!document.hidden&&ready()&&!browsingOlder&&online()&&!document.querySelector('#moment-dialog')?.open)void loadFeed()},30000);
